      statements.push(env.DB.prepare("INSERT INTO question_bank_items(question_id,sample_key,source_id,category,subcategory,provenance,source_reference,tags_json,review_status) VALUES(?,?,'qsrc-internal','cloze',?,'source_adapted',?,?, 'needs_review')").bind(qid,randomD1SampleKey(),questionType,`${source.name} · ${extracted.url}`,JSON.stringify([schoolLevel,topic,"content_source"])));
