async function listeningImport(id:string,req:Record<string,unknown>,env:JobEnv):Promise<boolean>{
  if(!env.MODELBRIDGE_API_KEY||!env.MODELBRIDGE_CHAT_MODEL)throw new Error("ModelBridge is not configured");
  if(!env.TASK_QUEUE)throw new Error("TASK_QUEUE producer binding is required for staged listening jobs");
  const sourceId=String(req.sourceId||""),schoolLevel=req.schoolLevel==="P5"?"P5":"P6",topic=String(req.topic||"Listening Practice"),contentId=String(req.contentId||"");
  const item=req.item as ListeningDiscoveredItem|undefined;
  if(!item?.title||!item.url||!item.provider||!item.id)throw new Error("Discovered item is missing");
  const pipeline=(req.__pipeline&&typeof req.__pipeline==="object"?req.__pipeline:{}) as Record<string,unknown>;
  const phase=typeof pipeline.phase==="string"?pipeline.phase:"prepare";

  if(phase==="prepare"){
    const source=await env.DB.prepare("SELECT * FROM listening_sources WHERE id=? AND enabled=1").bind(sourceId).first<ListeningSource>();
    if(!source)throw new Error("Listening source not found or disabled");
    await ensureActive(env.DB,id);
    await env.DB.prepare("UPDATE content_items SET generation_stage='preparing_source',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(contentId).run();
    const next={...req,__pipeline:{phase:"generate",sourceName:source.name}};
    await checkpointListeningJob(id,next,env,"source_prepared",25);
    return false;
  }

  if(phase==="generate"){
    const source=await env.DB.prepare("SELECT * FROM listening_sources WHERE id=? AND enabled=1").bind(sourceId).first<ListeningSource>();
    if(!source)throw new Error("Listening source not found or disabled");
    let basis:QuestionBasis="metadata_only",basisText="";
    const teacherTranscript=typeof req.teacherTranscript==="string"?req.teacherTranscript.trim():"",useCompanion=req.useCompanion===true;
    await setJob(env.DB,id,{stage:"preparing_ai_basis",progress:38});
    if(teacherTranscript.length>=120){basis="teacher_transcript";basisText=teacherTranscript.slice(0,18000);}
    else if(useCompanion&&item.companionUrl){
      const companionHost=item.companionAllowedHost||source.allowed_host;
      if(companionHost){
        await setJob(env.DB,id,{stage:"fetching_companion",progress:42});
        try{const extracted=await extractSource(item.companionUrl,companionHost);basis="companion_text";basisText=extracted.text.slice(0,18000);}catch{basis="metadata_only";basisText="";}
      }
    }
    await ensureActive(env.DB,id);
    await env.DB.prepare("UPDATE content_items SET generation_stage='generating',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(contentId).run();
    await setJob(env.DB,id,{stage:"generating_with_ai",progress:55});
    await appendJobLog(env.DB,id,{eventType:"listening_input",stage:"generating_with_ai",message:"Prepared listening material request",details:{sourceId,schoolLevel,topic,basis,item}});
    const currentJob=await getJob(env.DB,id),replay=currentJob&&currentJob.retry_count>0?await getLatestModelBridgeResponse(env.DB,id):null;
    if(replay)await appendJobLog(env.DB,id,{eventType:"modelbridge_replay",stage:"generating_with_ai",message:"Reusing historical ModelBridge response; no new model request was sent",details:{sourceLogId:replay.logId,originalCreatedAt:replay.createdAt,status:replay.status}});
    const material=await createListeningMaterial({baseUrl:env.MODELBRIDGE_BASE_URL,apiKey:env.MODELBRIDGE_API_KEY,model:env.MODELBRIDGE_CHAT_MODEL,schoolLevel,topic,sourceTitle:item.title,sourceDescription:item.description,basis,basisText,responseOverride:replay?.response,trace:async event=>{await appendJobLog(env.DB,id,{level:event.phase==="error"?"error":"info",eventType:`modelbridge_${event.phase}`,stage:"generating_with_ai",message:event.phase==="request"?"ModelBridge request sent":event.phase==="response"?`ModelBridge response ${event.status||""}`:`ModelBridge error ${event.status||""}`,details:event})}});
    await appendJobLog(env.DB,id,{eventType:"model_output_validated",stage:"generating_with_ai",message:"Model output validated",details:{title:material.title,topic:material.topic,questionCount:material.questions.length}});
    // Do not persist fetched companion/transcript basis between invocations. Only the
    // generated, validated lesson material and its basis type are checkpointed.
    const next={...req,teacherTranscript:"",__pipeline:{phase:"persist",sourceName:source.name,basis,material}};
    await checkpointListeningJob(id,next,env,"ai_generated",72);
    return false;
  }

  if(phase!=="persist")throw new Error(`Unknown listening pipeline phase: ${phase}`);
  const sourceName=String(pipeline.sourceName||"Listening source");
  const basis=(pipeline.basis==="teacher_transcript"||pipeline.basis==="companion_text"?pipeline.basis:"metadata_only") as QuestionBasis;
  const material=pipeline.material as ListeningMaterial|undefined;
  if(!material?.title||!Array.isArray(material.questions))throw new Error("Listening pipeline checkpoint is missing validated material");
  const skillIds=Array.isArray(req.skillIds)?req.skillIds.filter((x):x is string=>typeof x==="string"&&x.startsWith("L-")):["L-MAIN","L-DETAIL","L-INFER"];
  await ensureActive(env.DB,id);
  await setJob(env.DB,id,{stage:"saving_lesson",progress:85});
  await appendJobLog(env.DB,id,{eventType:"saving_lesson",stage:"saving_lesson",message:"Saving generated lesson to D1 in a batched persistence step"});
  await populateListeningMaterial(env.DB,contentId,{material,schoolLevel,skillIds,generationModel:env.MODELBRIDGE_CHAT_MODEL,sourceAttribution:`${sourceName} · media hosted by original publisher`,sourceItemUrl:item.url,media:{mediaKind:item.provider==="youtube"?"youtube":item.provider==="publisher"?"external_video":"podcast",provider:item.provider==="youtube"?"YouTube":sourceName,externalId:item.provider==="youtube"?item.id:undefined,mediaUrl:item.mediaUrl,embedUrl:item.provider==="youtube"?`https://www.youtube-nocookie.com/embed/${encodeURIComponent(item.id)}?rel=0`:undefined,thumbnailUrl:item.thumbnailUrl,durationSeconds:item.durationSeconds,madeForKids:item.madeForKids,sourceTitle:item.title,questionBasis:basis,transcriptPolicy:"not_stored"}});
  // Deterministic import id makes the persistence checkpoint idempotent: a retry
  // after D1 persistence cannot create duplicate listening_import rows.
  const importId=`listen-import-${contentId}`;
  const statements:D1PreparedStatement[]=[];
  const catalogItemId=typeof req.catalogItemId==="string"?req.catalogItemId:"";
  if(catalogItemId)statements.push(env.DB.prepare("UPDATE listening_story_catalog SET import_count=import_count+1,last_imported_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=? AND NOT EXISTS (SELECT 1 FROM listening_imports WHERE id=?)").bind(catalogItemId,importId));
  statements.push(env.DB.prepare("INSERT OR REPLACE INTO listening_imports (id,source_id,source_item_url,source_title,external_media_id,media_kind,school_level,target_topic,question_basis,status) VALUES (?,?,?,?,?,?,?,?,?,'adapted')").bind(importId,sourceId,item.url,item.title,item.id,item.provider==="youtube"?"youtube":item.provider==="publisher"?"external_video":"podcast",schoolLevel,topic,basis));
  await env.DB.batch(statements);
  await setJob(env.DB,id,{status:"succeeded",stage:"complete",progress:100,result:{contentId,importId,title:material.title,questionBasis:basis},completed:true,request:{sourceId,schoolLevel,topic,contentId,item:{id:item.id,title:item.title,url:item.url,provider:item.provider}}});
  return true;
}
export async function enqueueJob(db:D1Database,env:JobEnv,args:{jobType:string;entityType?:string;entityId?:string;sourceId?:string;request:Record<string,unknown>;tenantId?:string|null;createdBy?:string}){const id=await createJob(db,{jobType:args.jobType,entityType:args.entityType,entityId:args.entityId,sourceId:args.sourceId,request:args.request,tenantId:args.tenantId,scope:args.tenantId?"tenant":"global",createdBy:args.createdBy});/* Persist the job↔entity link before dispatching any external work. */if(args.entityType==="content"&&args.entityId)await db.prepare("UPDATE content_items SET generation_job_id=?,generation_stage=COALESCE(generation_stage,'queued'),updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(id,args.entityId).run().catch(()=>null);if(args.entityType==="writing_submission"&&args.entityId)await db.prepare("UPDATE writing_submissions SET generation_job_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(id,args.entityId).run().catch(()=>null);if(args.entityType==="question_bank_question"&&args.entityId)await db.prepare("UPDATE question_bank_items SET generation_job_id=?,updated_at=CURRENT_TIMESTAMP WHERE question_id=?").bind(id,args.entityId).run().catch(()=>null);try{await dispatchJob(id,env);}catch(e){await failJob(db,id,e);throw e;}return id;}

