async function writingFeedback(id:string,req:Record<string,unknown>,env:JobEnv){
 if(!env.MODELBRIDGE_API_KEY||!env.MODELBRIDGE_CHAT_MODEL)throw new Error("ModelBridge is not configured");
 const submissionId=String(req.submissionId||""),childId=String(req.childId||""),schoolLevel=req.schoolLevel==="P5"?"P5":"P6",writingType=String(req.writingType||"continuous"),prompt=String(req.prompt||""),text=String(req.text||"");
 await setJob(env.DB,id,{stage:"evaluating_writing",progress:55});
 const feedback=await evaluateWriting({baseUrl:env.MODELBRIDGE_BASE_URL,apiKey:env.MODELBRIDGE_API_KEY,model:env.MODELBRIDGE_CHAT_MODEL,schoolLevel,writingType,prompt,text,plan:req.plan});
 await ensureActive(env.DB,id);
 const values=[feedback.scores.content,feedback.scores.organisation,feedback.scores.vocabulary,feedback.scores.grammar,feedback.scores.mechanics,feedback.scores.taskFulfilment];
 const reviewScore=Math.round(values.reduce((a,b)=>a+b,0)/values.length),passMark=clampPassScore(req.passMark),passed=reviewScore>=passMark;
 const storedFeedback={...feedback,reviewScore,passed,passMark};
 await env.DB.prepare("UPDATE writing_submissions SET status='reviewed',scores_json=?,feedback_json=?,review_score=?,passed=?,passed_at=CASE WHEN ?=1 THEN CURRENT_TIMESTAMP ELSE NULL END,updated_at=CURRENT_TIMESTAMP WHERE id=?")
  .bind(JSON.stringify(feedback.scores),JSON.stringify(storedFeedback),reviewScore,passed?1:0,passed?1:0,submissionId).run();
 const skillMap:[string,number][]=[["W-CW-IDEAS",feedback.scores.content],["W-CW-ORG",feedback.scores.organisation],["W-CW-VOCAB",feedback.scores.vocabulary],["W-CW-GRAM",feedback.scores.grammar],["W-CW-MECH",feedback.scores.mechanics]];
 for(const [skill,score] of skillMap){const current=await env.DB.prepare("SELECT mastery,evidence_count FROM skill_mastery WHERE child_id=? AND skill_id=?").bind(childId,skill).first<{mastery:number;evidence_count:number}>();const n=current?Math.round((current.mastery*current.evidence_count+score)/(current.evidence_count+1)):score;await env.DB.prepare("INSERT INTO skill_mastery (child_id,skill_id,mastery,evidence_count,confidence,last_evidence_at,updated_at) VALUES (?,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(child_id,skill_id) DO UPDATE SET mastery=excluded.mastery,evidence_count=skill_mastery.evidence_count+1,confidence=MIN(1,skill_mastery.confidence+0.08),last_evidence_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP").bind(childId,skill,n,1,0.2).run();}
 await env.DB.prepare("INSERT INTO xp_ledger (id,child_id,event_type,points,reference_id) VALUES (?,?, 'writing_review', ?, ?)").bind(`xp-${crypto.randomUUID()}`,childId,passed?20:8,submissionId).run();
 const promptId=String(req.promptId||"");
 if(passed){
  await completeMatchingTasks(env.DB,childId,"writing",promptId||undefined);
 }
 await setJob(env.DB,id,{status:"succeeded",stage:passed?"passed":"revision_required",progress:100,result:{submissionId,feedback:storedFeedback,reviewScore,passed,passMark},completed:true,request:{submissionId,childId,promptId,schoolLevel,writingType,prompt,text:"redacted_after_generation"}});
}

async function specialisedOralEval(id:string,req:Record<string,unknown>,env:JobEnv){
 if(!env.MODELBRIDGE_API_KEY||!env.MODELBRIDGE_CHAT_MODEL)throw new Error("ModelBridge is not configured");const sessionId=String(req.sessionId||""),itemId=String(req.itemId||""),childId=String(req.childId||""),questionId=String(req.questionId||""),prompt=String(req.prompt||""),text=String(req.text||""),marks=Math.max(1,Number(req.marks)||4);await setJob(env.DB,id,{stage:"evaluating_oral",progress:55});const questionType=String(req.questionType||""),referenceText=String(req.referenceText||"");let pct:number,feedback:unknown;if(questionType==="oral_reading_aloud"&&referenceText){const estimate=heuristicPronunciation(referenceText,text,Math.max(1000,Math.round(text.trim().split(/\s+/).filter(Boolean).length/115*60000)));pct=Math.round((estimate.accuracy*0.45)+(estimate.completeness*0.35)+(estimate.fluency*0.20));feedback={readingAloud:estimate,note:"Text-recognition practice estimate; use the dedicated acoustic provider for pronunciation/prosody scoring."};}else{const f=await evaluateConversation({baseUrl:env.MODELBRIDGE_BASE_URL,apiKey:env.MODELBRIDGE_API_KEY,model:env.MODELBRIDGE_CHAT_MODEL,prompt,transcript:text,mode:questionType==="oral_stimulus"?"stimulus":"conversation",history:[]});pct=Math.round((f.relevance+f.development+f.grammar+f.vocabulary+f.interaction)/5);feedback=f;}await ensureActive(env.DB,id);const score=Math.round((pct/100*marks)*10)/10;await env.DB.prepare("UPDATE specialised_session_items SET score=?,max_score=?,feedback_json=?,status='completed',completed_at=CURRENT_TIMESTAMP WHERE id=?").bind(score,marks,JSON.stringify({percent:pct,feedback}),itemId).run();const skills=await env.DB.prepare("SELECT skill_id FROM question_skills WHERE question_id=?").bind(questionId).all<{skill_id:string}>();for(const sk of skills.results)await updateSkillEvidence(env.DB,childId,sk.skill_id,pct);await finaliseSpecialisedSession(env.DB,sessionId);await env.DB.prepare("UPDATE specialised_sessions SET status=CASE WHEN status='completed' THEN 'completed' ELSE 'active' END WHERE id=?").bind(sessionId).run();await setJob(env.DB,id,{status:"succeeded",stage:"complete",progress:100,result:{sessionId,itemId,score,maxScore:marks},completed:true,request:{sessionId,itemId,childId,questionId,text:"redacted_after_generation"}});
}
